/* eslint-disable no-console */
import { copyFileSync, existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { type FullConfig, request } from '@playwright/test';
import { ApiClient } from './client';
import { disableCoverageRecording } from './coverage/recorder';
import {
  assertDisposableTarget,
  COVERAGE_DIR,
  LOCAL_OPENAPI_FILE,
  OPENAPI_FILE,
  SEED_FILE,
} from './paths';
import { seedEnvironment } from './seed/setup';

const HEARTBEAT_TIMEOUT_MS = 120_000;

async function waitForHeartbeat(baseURL: string, timeoutMs: number) {
  const deadline = Date.now() + timeoutMs;
  let lastError = '';

  while (Date.now() < deadline) {
    try {
      const response = await fetch(`${baseURL}/api/heartbeat`);

      if (response.ok) {
        return;
      }

      lastError = `HTTP ${response.status}`;
    } catch (error) {
      lastError = (error as Error).message;
    }

    await new Promise(resolve => setTimeout(resolve, 1000));
  }

  throw new Error(
    `Timed out waiting for ${baseURL}/api/heartbeat (${lastError}). ` +
      'Start the stack with `pnpm test:api:up` or run the full flow with `pnpm test:api`.',
  );
}

/**
 * The coverage oracle must describe the server actually under test, so fetch its
 * generated OpenAPI document rather than assuming a local `pnpm build` ran.
 * public/openapi.json is a gitignored build artifact and is usually absent in a
 * checkout that only runs the Compose stack.
 */
async function fetchOpenApiDocument(baseURL: string) {
  const url = `${baseURL}/openapi.json`;

  try {
    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    const document = await response.json();

    if (!document?.paths) {
      throw new Error('response has no "paths" object');
    }

    writeFileSync(OPENAPI_FILE, JSON.stringify(document));
    return;
  } catch (error) {
    if (existsSync(LOCAL_OPENAPI_FILE)) {
      console.warn(
        `Could not fetch ${url} (${(error as Error).message}); ` +
          `using the locally generated ${LOCAL_OPENAPI_FILE} as the coverage oracle instead.`,
      );
      copyFileSync(LOCAL_OPENAPI_FILE, OPENAPI_FILE);
      return;
    }

    throw new Error(
      `Could not fetch the OpenAPI document from ${url} (${(error as Error).message}) and no ` +
        `local ${LOCAL_OPENAPI_FILE} exists. The server under test must serve its generated spec ` +
        '(it is built by `pnpm build:openapi`), or generate it locally with `pnpm openapi:generate`.',
    );
  }
}

export default async function globalSetup(config: FullConfig) {
  // Seeding traffic must not count towards endpoint coverage.
  disableCoverageRecording();

  const baseURL = config.projects[0]?.use?.baseURL;

  if (!baseURL) {
    throw new Error('playwright.api.config.ts must define use.baseURL');
  }

  assertDisposableTarget(baseURL);

  // API_SKIP_SEED=1 reuses the seed from a previous run against a kept stack
  // (fast iteration on a single spec).
  const skipSeed = !!process.env.API_SKIP_SEED && existsSync(SEED_FILE);

  // Coverage must reflect this run only: the per-process logs are append-only and
  // the reporter merges every file in the directory, so stale logs from an earlier
  // run would let removed endpoint calls still count as covered.
  rmSync(COVERAGE_DIR, { recursive: true, force: true });
  mkdirSync(COVERAGE_DIR, { recursive: true });

  console.log(`Waiting for ${baseURL}/api/heartbeat ...`);
  await waitForHeartbeat(baseURL, HEARTBEAT_TIMEOUT_MS);
  await fetchOpenApiDocument(baseURL);

  if (skipSeed) {
    console.log(`Reusing seed state from ${SEED_FILE} (API_SKIP_SEED is set).`);
    return;
  }

  const context = await request.newContext({ baseURL });

  try {
    const started = Date.now();
    const state = await seedEnvironment(new ApiClient(context));

    writeFileSync(SEED_FILE, JSON.stringify(state, null, 2));

    console.log(
      `Seeded ${state.db} environment in ${((Date.now() - started) / 1000).toFixed(1)}s ` +
        `(${state.data.expectedPageviews} pageviews on ${state.website.domain})`,
    );
  } finally {
    await context.dispose();
  }
}

import { expect, test } from './fixtures';
import { login } from './helpers/auth';

test.describe('Auth', () => {
  test('POST /api/auth/login returns a token and the user', async ({ api, seed }) => {
    const response = await api.post('/api/auth/login', {
      username: seed.admin.username,
      password: seed.admin.password,
    });

    expect(response.status).toBe(200);
    expect(response.body).toMatchObject({
      token: expect.any(String),
      user: {
        id: seed.admin.id,
        username: seed.admin.username,
        role: 'admin',
        createdAt: expect.any(String),
        isAdmin: true,
        teams: expect.any(Array),
      },
    });
    expect(response.body).not.toHaveProperty('requiresTwoFactor');
    expect(response.body.user).not.toHaveProperty('password');
  });

  test('POST /api/auth/login matches usernames case-insensitively', async ({ api, seed }) => {
    const response = await api.post('/api/auth/login', {
      username: seed.user.username.toUpperCase(),
      password: seed.user.password,
    });

    expect(response.status).toBe(200);
    expect(response.body.token).toEqual(expect.any(String));
    expect(response.body.user).toMatchObject({ id: seed.user.id, role: 'user', isAdmin: false });
    // The response echoes the submitted username verbatim; the lookup itself is case-insensitive.
    expect(response.body.user.username.toLowerCase()).toBe(seed.user.username);
    expect(response.body.user.teams.map((t: any) => t.id)).toContain(seed.team.id);

    // The session resolves to the stored (lowercase) username.
    const me = await api.bearer(response.body.token).get('/api/me');

    expect(me.status).toBe(200);
    expect(me.body.user).toMatchObject({ id: seed.user.id, username: seed.user.username });
  });

  test('POST /api/auth/login rejects bad credentials', async ({ api, seed }) => {
    const wrongPassword = await api.post('/api/auth/login', {
      username: seed.admin.username,
      password: 'not-the-password',
    });
    const unknownUser = await api.post('/api/auth/login', {
      username: 'no-such-user',
      password: seed.admin.password,
    });

    expect(wrongPassword.status).toBe(401);
    expect(wrongPassword.body.error).toMatchObject({
      code: 'incorrect-username-password',
      status: 401,
    });
    expect(unknownUser.status).toBe(401);
    expect(unknownUser.body.error.code).toBe('incorrect-username-password');
  });

  test('POST /api/auth/login validates the body', async ({ api, seed }) => {
    const missingPassword = await api.post('/api/auth/login', { username: seed.admin.username });
    const missingUsername = await api.post('/api/auth/login', { password: seed.admin.password });
    const empty = await api.post('/api/auth/login', {});

    expect(missingPassword.status).toBe(400);
    expect(missingUsername.status).toBe(400);
    expect(empty.status).toBe(400);
    expect(empty.body.error).toMatchObject({ status: 400 });
  });

  test('POST /api/auth/verify returns the current session', async ({ admin, user, seed }) => {
    const response = await admin.post('/api/auth/verify');
    const asUser = await user.post('/api/auth/verify');

    expect(response.status).toBe(200);
    // The body is the flat user record plus its teams.
    expect(response.body).toMatchObject({
      id: seed.admin.id,
      username: seed.admin.username,
      role: 'admin',
      createdAt: expect.any(String),
      isAdmin: true,
      twoFactorRequired: expect.any(Boolean),
      teams: expect.any(Array),
    });
    expect(response.body).not.toHaveProperty('password');
    expect(asUser.status).toBe(200);
    expect(asUser.body.id).toBe(seed.user.id);
    expect(asUser.body.teams.map((t: any) => t.id)).toContain(seed.team.id);
  });

  test('POST /api/auth/verify rejects anonymous, invalid and API key callers', async ({
    api,
    apiKey,
  }) => {
    const anonymous = await api.post('/api/auth/verify');
    const garbage = await api.bearer('not-a-token').post('/api/auth/verify');
    const viaApiKey = await apiKey.post('/api/auth/verify');

    expect(anonymous.status).toBe(401);
    expect(garbage.status).toBe(401);
    // API keys are blocked on /api/auth/*.
    expect(viaApiKey.status).toBe(401);
  });

  test('POST /api/auth/logout acknowledges the logout', async ({ api, seed }) => {
    // Use a dedicated session so the shared worker tokens are never touched.
    const token = await login(api, seed.viewer);
    const response = await api.bearer(token).post('/api/auth/logout');

    expect(response.status).toBe(200);
    expect(response.body).toEqual({ ok: true });
    // Without Redis the stateless token remains valid, so no follow-up 401 is asserted.
  });

  test('POST /api/auth/logout requires a session', async ({ api, apiKey }) => {
    const anonymous = await api.post('/api/auth/logout');
    const viaApiKey = await apiKey.post('/api/auth/logout');

    expect(anonymous.status).toBe(401);
    expect(viaApiKey.status).toBe(401);
  });
});

import type { ApiClient } from '../client';
import { login } from '../helpers/auth';
import { ADMIN_USER } from '../helpers/constants';
import { assertStatus } from '../helpers/entities';
import { buildDataset, CURRENCY, type Dataset, HOSTNAME } from './dataset';
import {
  SEED_IDS,
  SEED_LINK,
  SEED_PIXEL,
  SEED_SHARE,
  SEED_TEAM,
  SEED_USERS,
  SEED_WEBSITES,
} from './ids';
import { type IngestResult, ingestDataset } from './ingest';
import type { SeedCredentials, SeedState } from './state';

const READINESS_TIMEOUT_MS = 60_000;

async function ensureUser(
  admin: ApiClient,
  credentials: { username: string; password: string; role: string },
): Promise<SeedCredentials> {
  const created = await admin.post('/api/users', credentials);

  if (created.status === 200) {
    return { ...credentials, id: created.body.id };
  }

  if (created.status !== 400) {
    throw new Error(
      `Failed to create ${credentials.username} (${created.status}): ${created.text}`,
    );
  }

  // Already exists (re-run against a kept stack): look it up.
  const users = assertStatus(
    await admin.get('/api/admin/users', { params: { search: credentials.username } }),
    200,
    'list users',
  );
  const user = users.body.data?.find((u: any) => u.username === credentials.username);

  if (!user) {
    throw new Error(`User ${credentials.username} exists but could not be found`);
  }

  return { ...credentials, id: user.id };
}

async function recreateWebsite(
  client: ApiClient,
  id: string,
  data: { name: string; domain: string },
) {
  const existing = await client.get(`/api/websites/${id}`);

  // Admins bypass the permission check, so an unknown id yields 200 with a null body.
  if (existing.status === 200 && existing.body?.id) {
    assertStatus(await client.del(`/api/websites/${id}`), 200, `delete website ${id}`);
  }

  return assertStatus(await client.post('/api/websites', { id, ...data }), 200, 'create website')
    .body;
}

async function ensureEntity(
  client: ApiClient,
  collection: 'links' | 'pixels',
  id: string,
  data: Record<string, unknown>,
) {
  const existing = await client.get(`/api/${collection}/${id}`);

  if (existing.status === 200 && existing.body?.id) {
    return existing.body;
  }

  return assertStatus(
    await client.post(`/api/${collection}`, { id, ...data }),
    200,
    `create ${collection}`,
  ).body;
}

async function ensureTeam(admin: ApiClient, memberId: string) {
  const teams = assertStatus(await admin.get('/api/teams'), 200, 'list teams');
  let team = teams.body.data?.find((t: any) => t.name === SEED_TEAM.name);

  if (!team) {
    const created = assertStatus(await admin.post('/api/teams', SEED_TEAM), 200, 'create team');
    team = created.body[0];
  }

  const detail = assertStatus(await admin.get(`/api/teams/${team.id}`), 200, 'get team').body;
  const member = await admin.post(`/api/teams/${team.id}/users`, {
    userId: memberId,
    role: 'team-member',
  });

  // 400 = already a member (re-run).
  if (member.status !== 200 && member.status !== 400) {
    throw new Error(`Failed to add team member (${member.status}): ${member.text}`);
  }

  return {
    id: detail.id as string,
    name: detail.name as string,
    accessCode: detail.accessCode as string,
  };
}

async function poll<T>(label: string, fn: () => Promise<T | undefined>, timeoutMs: number) {
  const deadline = Date.now() + timeoutMs;
  let last: string | undefined;

  while (Date.now() < deadline) {
    try {
      const result = await fn();

      if (result !== undefined) {
        return result;
      }
    } catch (error) {
      last = (error as Error).message;
    }

    await new Promise(resolve => setTimeout(resolve, 500));
  }

  throw new Error(`Timed out waiting for ${label}${last ? ` (${last})` : ''}`);
}

/**
 * Waits until the analytics queries see the ingested data (ClickHouse
 * materialized views are synchronous, but this guards against any lag) and
 * harvests ids that specs need for path parameters.
 */
async function waitForAnalytics(admin: ApiClient, dataset: Dataset, ingested: IngestResult) {
  const websiteId = SEED_IDS.website;
  const range = () => ({ startAt: dataset.range.startAt, endAt: Date.now() });

  await poll(
    `${dataset.expected.pageviews} pageviews on ${websiteId}`,
    async () => {
      const response = await admin.get(`/api/websites/${websiteId}/stats`, { params: range() });
      // /stats returns flat numbers (possibly as strings under Postgres bigint).
      const pageviews = Number(response.body?.pageviews ?? 0);

      return pageviews >= dataset.expected.pageviews ? pageviews : undefined;
    },
    READINESS_TIMEOUT_MS,
  );

  const sessionId = await poll(
    'a session',
    async () => {
      const response = await admin.get(`/api/websites/${websiteId}/sessions`, {
        params: { ...range(), pageSize: 1 },
      });

      return response.body?.data?.[0]?.id as string | undefined;
    },
    READINESS_TIMEOUT_MS,
  );

  const eventId = await poll(
    'a custom event with data',
    async () => {
      const response = await admin.get(`/api/websites/${websiteId}/events`, {
        params: { ...range(), pageSize: 50, eventType: 2 },
      });
      const event = response.body?.data?.find((e: any) => e.hasData);

      return event?.id as string | undefined;
    },
    READINESS_TIMEOUT_MS,
  );

  await poll(
    'the recorded replay',
    async () => {
      const response = await admin.get(`/api/websites/${websiteId}/replays`, {
        params: range(),
      });

      return response.body?.data?.some((r: any) => r.id === ingested.replay.visitId)
        ? true
        : undefined;
    },
    READINESS_TIMEOUT_MS,
  );

  return { sessionId, eventId };
}

export async function seedEnvironment(api: ApiClient): Promise<SeedState> {
  const db = process.env.UMAMI_TEST_DB === 'clickhouse' ? 'clickhouse' : 'postgres';

  const admin = api.bearer(await login(api, ADMIN_USER));
  const user = await ensureUser(admin, SEED_USERS.user);
  const viewer = await ensureUser(admin, SEED_USERS.viewer);
  const userApi = api.bearer(await login(api, SEED_USERS.user));

  const website = await recreateWebsite(admin, SEED_IDS.website, SEED_WEBSITES.primary);
  const website2 = await recreateWebsite(userApi, SEED_IDS.website2, SEED_WEBSITES.secondary);

  assertStatus(
    await admin.post(`/api/websites/${website.id}`, {
      replayConfig: {
        replayEnabled: true,
        heatmapEnabled: true,
        sampleRate: 1,
        heatmapSampleRate: 1,
      },
    }),
    200,
    'enable recorder',
  );

  const share = assertStatus(
    await admin.post(`/api/websites/${website.id}/shares`, { ...SEED_SHARE, parameters: {} }),
    200,
    'create share',
  ).body;

  const link = await ensureEntity(admin, 'links', SEED_IDS.link, SEED_LINK);
  const pixel = await ensureEntity(admin, 'pixels', SEED_IDS.pixel, SEED_PIXEL);
  const team = await ensureTeam(admin, user.id);

  const dataset = buildDataset();
  const ingested = await ingestDataset(api, dataset);
  const { sessionId, eventId } = await waitForAnalytics(admin, dataset, ingested);

  return {
    db,
    createdAt: new Date().toISOString(),
    admin: { ...ADMIN_USER },
    user,
    viewer,
    website: { id: website.id, name: website.name, domain: website.domain },
    website2: { id: website2.id, name: website2.name, domain: website2.domain },
    link: { id: link.id, name: link.name, url: link.url, slug: link.slug },
    pixel: { id: pixel.id, name: pixel.name, slug: pixel.slug },
    team,
    share: { id: share.id, slug: share.slug },
    range: dataset.range,
    data: {
      hostname: HOSTNAME,
      currency: CURRENCY,
      pages: dataset.pages,
      eventNames: dataset.eventNames,
      distinctIds: dataset.distinctIds,
      expectedPageviews: dataset.expected.pageviews,
      expectedWebsite2Pageviews: dataset.expected.website2Pageviews,
      sessionId,
      eventId,
      replayVisitId: ingested.replay.visitId,
      replaySessionId: ingested.replay.sessionId,
    },
  };
}

import type { ApiClient } from '../client';

export interface Credentials {
  username: string;
  password: string;
}

export async function login(api: ApiClient, { username, password }: Credentials) {
  const response = await api.post('/api/auth/login', { username, password });

  if (response.status !== 200 || !response.body?.token) {
    throw new Error(`Login failed for ${username} (${response.status}): ${response.text}`);
  }

  return response.body.token as string;
}

import { beforeEach, describe, expect, test, vi } from 'vitest';
import { checkApiKeyAuth } from '@/lib/auth';
import { authenticateMcpRequest, mcpAuthErrorResponse } from './auth';

vi.mock('@/lib/auth', () => ({
  getBearerToken: (request: Request) => request.headers.get('authorization')?.split(' ')[1],
  checkApiKeyAuth: vi.fn(),
}));

const checkApiKeyAuthMock = vi.mocked(checkApiKeyAuth);

function request(token?: string) {
  return new Request('https://analytics.example.com/mcp', {
    method: 'POST',
    headers: token ? { authorization: `Bearer ${token}` } : {},
  });
}

beforeEach(() => {
  vi.unstubAllEnvs();
  vi.stubEnv('CLOUD_MODE', '');
  checkApiKeyAuthMock.mockReset();
});

describe('authenticateMcpRequest', () => {
  test('rejects missing tokens with an API key challenge', async () => {
    const result = await authenticateMcpRequest(request());
    const response = mcpAuthErrorResponse(result);

    expect(response.status).toBe(401);
    expect(response.headers.get('www-authenticate')).toBe(
      'Bearer realm="Umami MCP", error="invalid_request"',
    );
    expect(response.headers.get('cache-control')).toBe('no-store');
  });

  test.each(['not-a-token', 'not-a-key'])(
    'rejects non-API-key credentials: %s',
    async token => {
      await expect(authenticateMcpRequest(request(token))).resolves.toMatchObject({
        ok: false,
        status: 401,
      });
      expect(checkApiKeyAuthMock).not.toHaveBeenCalled();
    },
  );

  test('accepts self-hosted API keys and preserves owner identity', async () => {
    checkApiKeyAuthMock.mockResolvedValue({
      token: 'umami_key',
      user: { id: 'user-1' },
      apiKey: { id: 'key-1', name: 'MCP' },
    } as never);

    await expect(authenticateMcpRequest(request('umami_key'))).resolves.toMatchObject({
      ok: true,
      userId: 'user-1',
      authInfo: {
        token: 'umami_key',
        clientId: 'api-key:key-1',
        scopes: [],
        extra: { userId: 'user-1', authType: 'api-key' },
      },
    });
  });

  test('rejects revoked or unknown keys', async () => {
    checkApiKeyAuthMock.mockResolvedValue(null);
    await expect(authenticateMcpRequest(request('umami_revoked'))).resolves.toMatchObject({
      ok: false,
      status: 401,
      error: 'invalid_token',
    });
  });

  test('rejects self-hosted keys in Cloud mode', async () => {
    vi.stubEnv('CLOUD_MODE', '1');
    await expect(authenticateMcpRequest(request('umami_key'))).resolves.toMatchObject({
      ok: false,
      status: 401,
    });
    expect(checkApiKeyAuthMock).not.toHaveBeenCalled();
  });
});

import { beforeEach, expect, test, vi } from 'vitest';
import { POST } from './route';

const mocks = vi.hoisted(() => {
  const tx = {
    twoFactorAuth: {
      update: vi.fn(),
    },
    twoFactorBackupCode: {
      deleteMany: vi.fn(),
      createMany: vi.fn(),
    },
  };

  return {
    parseRequest: vi.fn(),
    findUnique: vi.fn(),
    transaction: vi.fn(),
    tx,
    generateBackupCodes: vi.fn(),
    decryptSecret: vi.fn(),
    isTwoFactorConfigured: vi.fn(),
    checkRateLimit: vi.fn(),
    recordFailedAttempt: vi.fn(),
    resetRateLimit: vi.fn(),
    isOtpReplayed: vi.fn(),
    markOtpUsed: vi.fn(),
    verifyTotp: vi.fn(),
  };
});

vi.mock('@/lib/request', () => ({
  parseRequest: mocks.parseRequest,
}));

vi.mock('@/lib/prisma', () => ({
  default: {
    client: {
      twoFactorAuth: {
        findUnique: mocks.findUnique,
      },
    },
    transaction: mocks.transaction,
  },
}));

vi.mock('@/lib/two-factor/backup-codes', () => ({
  generateBackupCodes: mocks.generateBackupCodes,
}));

vi.mock('@/lib/two-factor/crypto', () => ({
  decryptSecret: mocks.decryptSecret,
  getTwoFactorConfigurationError: () => ({
    code: 'two-factor-error-not-configured',
    message: 'TWO_FACTOR_ENCRYPTION_KEY is missing or invalid',
  }),
  isTwoFactorConfigured: mocks.isTwoFactorConfigured,
}));

vi.mock('@/lib/two-factor/rate-limit', () => ({
  checkRateLimit: mocks.checkRateLimit,
  recordFailedAttempt: mocks.recordFailedAttempt,
  resetRateLimit: mocks.resetRateLimit,
}));

vi.mock('@/lib/two-factor/replay-prevention', () => ({
  isOtpReplayed: mocks.isOtpReplayed,
  markOtpUsed: mocks.markOtpUsed,
}));

vi.mock('@/lib/two-factor/totp', () => ({
  verifyTotp: mocks.verifyTotp,
}));

beforeEach(() => {
  mocks.parseRequest.mockReset();
  mocks.findUnique.mockReset();
  mocks.transaction.mockReset();
  mocks.tx.twoFactorAuth.update.mockReset();
  mocks.tx.twoFactorBackupCode.deleteMany.mockReset();
  mocks.tx.twoFactorBackupCode.createMany.mockReset();
  mocks.generateBackupCodes.mockReset();
  mocks.decryptSecret.mockReset();
  mocks.isTwoFactorConfigured.mockReset();
  mocks.checkRateLimit.mockReset();
  mocks.recordFailedAttempt.mockReset();
  mocks.resetRateLimit.mockReset();
  mocks.isOtpReplayed.mockReset();
  mocks.markOtpUsed.mockReset();
  mocks.verifyTotp.mockReset();

  mocks.parseRequest.mockResolvedValue({
    auth: { user: { id: 'user-1' } },
    body: { token: '123456' },
    error: undefined,
  });
  mocks.findUnique.mockResolvedValue({ userId: 'user-1', isEnabled: false, secret: 'encrypted' });
  mocks.transaction.mockImplementation(async callback => callback(mocks.tx));
  mocks.generateBackupCodes.mockResolvedValue({
    plaintext: ['code-1', 'code-2'],
    hashed: ['hash-1', 'hash-2'],
  });
  mocks.decryptSecret.mockReturnValue('plain-secret');
  mocks.isTwoFactorConfigured.mockReturnValue(true);
  mocks.checkRateLimit.mockResolvedValue({ allowed: true });
  mocks.recordFailedAttempt.mockResolvedValue({ lockedUntil: undefined });
  mocks.resetRateLimit.mockResolvedValue(undefined);
  mocks.isOtpReplayed.mockResolvedValue(false);
  mocks.markOtpUsed.mockResolvedValue(undefined);
  mocks.verifyTotp.mockResolvedValue(true);
  mocks.tx.twoFactorAuth.update.mockResolvedValue(undefined);
  mocks.tx.twoFactorBackupCode.deleteMany.mockResolvedValue(undefined);
  mocks.tx.twoFactorBackupCode.createMany.mockResolvedValue(undefined);
});

test('POST confirms setup, enables 2FA, stores backup codes, and resets the rate limit', async () => {
  const response = await POST(
